CREATE DATABASE IF NOT EXISTS golf_erp CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE golf_erp;
CREATE TABLE IF NOT EXISTS members (id BIGINT PRIMARY KEY AUTO_INCREMENT, member_no VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, phone VARCHAR(30), email VARCHAR(120), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_members_name(name), INDEX idx_members_phone(phone));
CREATE TABLE IF NOT EXISTS golf_courses (id BIGINT PRIMARY KEY AUTO_INCREMENT, course_code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, hole_count INT NOT NULL DEFAULT 18, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reservations (id BIGINT PRIMARY KEY AUTO_INCREMENT, reservation_no VARCHAR(30) NOT NULL UNIQUE, member_id BIGINT NOT NULL, course_id BIGINT NOT NULL, reserved_at DATETIME NOT NULL, player_count INT NOT NULL DEFAULT 4, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', memo VARCHAR(500), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_res_member FOREIGN KEY(member_id) REFERENCES members(id), CONSTRAINT fk_res_course FOREIGN KEY(course_id) REFERENCES golf_courses(id), INDEX idx_res_reserved_at(reserved_at), INDEX idx_res_status_reserved(status,reserved_at));
CREATE TABLE IF NOT EXISTS fee_policies (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL, day_type VARCHAR(20) NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, amount DECIMAL(12,2) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments (id BIGINT PRIMARY KEY AUTO_INCREMENT, reservation_id BIGINT NOT NULL, amount DECIMAL(12,2) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'READY', paid_at DATETIME NULL, payment_method VARCHAR(30), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_payment_res FOREIGN KEY(reservation_id) REFERENCES reservations(id));
CREATE TABLE IF NOT EXISTS settlements (id BIGINT PRIMARY KEY AUTO_INCREMENT, settlement_date DATE NOT NULL UNIQUE, gross_amount DECIMAL(14,2) NOT NULL DEFAULT 0, refund_amount DECIMAL(14,2) NOT NULL DEFAULT 0, net_amount DECIMAL(14,2) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(80) NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'STAFF', active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor_username VARCHAR(60), action VARCHAR(80) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT, details JSON, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
